const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const exercises = [
 {id:'squat',name:'Sentadilla',category:'Tren inferior',muscle:'Cuádriceps · Glúteos',equipment:'Peso corporal',sets:3,reps:12,rest:60,steps:['Coloca los pies a una anchura cómoda.','Flexiona caderas y rodillas de forma controlada.','Vuelve a la posición inicial sin apresurarte.']},
 {id:'lunge',name:'Zancada hacia atrás',category:'Tren inferior',muscle:'Piernas · Glúteos',equipment:'Peso corporal',sets:3,reps:10,rest:60,steps:['Empieza de pie y lleva una pierna hacia atrás.','Flexiona ambas rodillas dentro de un rango cómodo.','Regresa al inicio y alterna el lado.']},
 {id:'bridge',name:'Puente de glúteos',category:'Tren inferior',muscle:'Glúteos · Cadena posterior',equipment:'Colchoneta',sets:3,reps:15,rest:45,steps:['Apoya la espalda y los pies sobre el suelo.','Eleva la cadera de forma controlada.','Desciende con suavidad a la posición inicial.']},
 {id:'row',name:'Remo con mancuernas',category:'Tren superior',muscle:'Espalda · Brazos',equipment:'Mancuernas',sets:3,reps:12,rest:60,steps:['Inclina el tronco desde la cadera.','Acerca los codos al tronco sin impulsarte.','Baja los brazos con control.']},
 {id:'curl',name:'Curl de bíceps',category:'Tren superior',muscle:'Bíceps',equipment:'Mancuernas',sets:3,reps:12,rest:60,steps:['Empieza con los brazos a los lados.','Flexiona los codos sin balancear el cuerpo.','Baja la carga de forma controlada.']},
 {id:'plank',name:'Plancha de antebrazos',category:'Core',muscle:'Abdomen · Estabilidad',equipment:'Colchoneta',sets:3,reps:30,rest:45,timed:true,steps:['Apoya los antebrazos y las puntas de los pies.','Mantén una línea cómoda entre hombros y caderas.','Respira de forma continua durante la posición.']}
];
const plans = [['squat','lunge','bridge'],['row','curl','plank'],['squat','row','plank']];
const planNames = ['Tren inferior','Tren superior','Cuerpo completo'];
const STORAGE_KEY = 'sosfit-demo-v1';
let storageAvailable=true;
let records=[];
try { const data=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]'); if(Array.isArray(data)) records=data.filter(r=>exercises.some(e=>e.id===r.exercise)&&Number.isInteger(r.day)&&r.day>=0&&r.day<3&&Number.isFinite(r.reps)&&Number.isFinite(r.load)&&!isNaN(Date.parse(r.date))); } catch {storageAvailable=false;}
let activeDay=0,activeExercise=null,activeFilter='Todos',motionPaused=matchMedia('(prefers-reduced-motion: reduce)').matches;
let animationFrame=0,motionTime=0,lastFrame=0,timerDeadline=null,timerInterval=0,remaining=60,toastTimeout;
const localDay = d => {const t=new Date(d);return `${t.getFullYear()}-${t.getMonth()+1}-${t.getDate()}`;};
const todayRecords = () => records.filter(r=>localDay(r.date)===localDay(new Date()));
const isDone = (id,day=activeDay) => todayRecords().some(r=>r.exercise===id&&r.day===day);
const getExercise = id => exercises.find(e=>e.id===id);
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').hidden=true,3500);}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(records));}catch{storageAvailable=false;toast('No se pudo guardar en este navegador. Los cambios durarán esta visita.');}}
function thumb(id){let shape={squat:'M23 17L20 31L30 39L16 50M26 31L41 39L48 50M23 23L11 32M25 23L38 31',lunge:'M25 17L25 32L12 40L13 52M26 32L41 39L44 52M24 22L12 30M26 22L38 30',bridge:'M6 45L17 39L32 33L45 40L48 52M32 33L39 49M16 40L20 50',row:'M19 20L34 32L24 42L29 53M34 32L43 51M25 25L19 37L29 33M28 27L36 38L42 32',curl:'M25 17L25 34L17 52M25 34L34 52M25 22L14 34L10 23M27 22L38 34L43 23',plank:'M9 37L22 35L38 39L52 47M22 35L18 48L7 48'}[id];let head=id==='bridge'?'cx="8" cy="39"':id==='plank'?'cx="9" cy="28"':'cx="25" cy="10"';return `<svg viewBox="0 0 60 60" aria-hidden="true"><path d="M4 55H56" stroke="#d4debf"/><path d="${shape}" stroke="#637d43" stroke-width="4" fill="none" stroke-linecap="round" stroke-linejoin="round"/><circle ${head} r="5" fill="#9cae78"/></svg>`;}
function renderRoutine(){
 $('#day-heading').textContent=planNames[activeDay];
 const done=plans[activeDay].filter(id=>isDone(id)).length;
 $('#session-count').textContent=`${done} de 3 completados hoy`;
 $('#exercise-list').innerHTML=plans[activeDay].map((id,i)=>{const e=getExercise(id);return `<article class="exercise-row"><button class="exercise-thumb" data-exercise="${id}" aria-label="Ver demostración de ${e.name}">${thumb(id)}</button><button class="exercise-name" data-exercise="${id}"><strong>${e.name}</strong><small>${String(i+1).padStart(2,'0')} &nbsp; ${e.muscle}</small></button><div class="exercise-info">${e.sets} × ${e.reps} ${e.timed?'seg':'reps'}<br><span class="muted">${e.rest}s descanso</span></div><button class="check-exercise ${isDone(id)?'done':''}" data-check="${id}" aria-label="${isDone(id)?'Desmarcar':'Registrar'} ${e.name}" aria-pressed="${isDone(id)}">${isDone(id)?'✓':''}</button></article>`;}).join('');
 const percentage=Math.round(done/3*100);$('#progress-ring').style.setProperty('--progress',percentage+'%');$('#progress-number').innerHTML=percentage+'<span>%</span>';
 $('#progress-message').textContent=done===3?'¡Sesión de ejemplo completada por hoy!':'Marca cada ejercicio cuando lo termines.';
 $('#total-done').textContent=records.length;
 const sessions=new Map();records.forEach(r=>{const key=localDay(r.date)+'-'+r.day;if(!sessions.has(key))sessions.set(key,new Set());sessions.get(key).add(r.exercise);});
 $('#total-sessions').textContent=[...sessions.values()].filter(s=>s.size===3).length;
 $$('.day').forEach((b,i)=>{b.classList.toggle('active',i===activeDay);b.setAttribute('aria-selected',i===activeDay);});
}
function renderLibrary(){const query=$('#search').value.trim().toLocaleLowerCase('es');const filtered=exercises.filter(e=>(activeFilter==='Todos'||e.category===activeFilter)&&`${e.name} ${e.muscle} ${e.equipment}`.toLocaleLowerCase('es').includes(query));$('#library-grid').innerHTML=filtered.length?filtered.map(e=>`<button class="library-card" data-exercise="${e.id}"><div class="library-art">${thumb(e.id)}</div><div class="library-copy"><span class="eyebrow">${e.category.toUpperCase()}</span><h3>${e.name}</h3><p>${e.equipment} · ${e.muscle}</p><span>Ver movimiento ↗</span></div></button>`).join(''):'<p class="empty">No encontramos ejercicios con ese nombre. Prueba otra búsqueda.</p>';}
function renderHistory(){const root=$('#history-list');root.replaceChildren();if(!records.length){root.innerHTML='<p class="empty">Tu historia empieza aquí.<br>Registra tu primer ejercicio desde una rutina.</p>';return;}[...records].reverse().forEach(r=>{const e=getExercise(r.exercise);const row=document.createElement('div');row.className='history-row';const text=document.createElement('div');const title=document.createElement('strong');title.textContent=e.name;const detail=document.createElement('span');detail.textContent=new Date(r.date).toLocaleString('es',{dateStyle:'medium',timeStyle:'short'})+' · Día '+(r.day+1);text.append(title,detail);const result=document.createElement('b');result.textContent=`${e.sets} × ${r.reps} ${e.timed?'seg':'reps'}${r.load?' · '+r.load+' kg':''}`;row.append(text,result);root.append(row);});}
function showView(view){$$('.view').forEach(s=>s.hidden=s.id!==view+'-view');$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#page-label').textContent={rutina:'Mi rutina',biblioteca:'Ejercicios',progreso:'Mi progreso'}[view];if(view==='progreso')renderHistory();if(view==='biblioteca')renderLibrary();}
// Original schematic poses. Arrays: head, shoulder, hip, left/right elbows,
// left/right hands, left/right knees, left/right feet. Not external API media.
const poses={
 squat:[[[160,55],[160,88],[160,175],[131,110],[188,110],[129,140],[191,140],[133,213],[188,213],[125,263],[195,263]],[[132,95],[143,126],[188,191],[121,135],[127,135],[88,123],[97,123],[126,211],[140,211],[125,263],[155,263]]],
 lunge:[[[160,55],[160,88],[160,175],[133,117],[188,117],[132,151],[188,151],[140,215],[181,215],[130,263],[192,263]],[[152,95],[152,128],[160,195],[127,148],[179,148],[124,177],[187,176],[111,207],[208,233],[110,263],[242,263]]],
 bridge:[[[70,232],[96,245],[172,249],[110,257],[112,258],[141,261],[144,261],[215,215],[218,221],[251,263],[254,263]],[[70,232],[96,245],[172,187],[110,257],[112,258],[141,261],[144,261],[215,213],[218,220],[251,263],[254,263]]],
 row:[[[106,103],[129,127],[195,178],[132,176],[148,178],[134,210],[150,210],[175,217],[212,217],[158,263],[229,263]],[[106,103],[129,127],[195,178],[167,121],[185,128],[159,163],[174,165],[175,217],[212,217],[158,263],[229,263]]],
 curl:[[[160,55],[160,88],[160,175],[130,130],[190,130],[126,174],[194,174],[140,218],[181,218],[132,263],[190,263]],[[160,55],[160,88],[160,175],[130,130],[190,130],[116,88],[205,88],[140,218],[181,218],[132,263],[190,263]]],
 plank:[[[80,185],[105,210],[190,226],[92,260],[116,260],[52,261],[79,261],[227,240],[228,242],[271,264],[274,264]],[[80,185],[105,210],[190,226],[92,260],[116,260],[52,261],[79,261],[227,240],[228,242],[271,264],[274,264]]]
};
function drawPose(id,t){const [a,b]=poses[id];const p=a.map((v,i)=>v.map((n,k)=>n+(b[i][k]-n)*t));const path=(...indices)=>indices.map((i,j)=>(j?'L':'M')+p[i].join(',')).join('');$('#torso').setAttribute('d',path(1,2));$('#leg-left').setAttribute('d',path(2,7,9));$('#leg-right').setAttribute('d',path(2,8,10));$('#arm-left').setAttribute('d',path(1,3,5));$('#arm-right').setAttribute('d',path(1,4,6));$('#figure-head').setAttribute('cx',p[0][0]);$('#figure-head').setAttribute('cy',p[0][1]);}
function animate(time){if(!$('#exercise-dialog').open)return;if(lastFrame&&!motionPaused)motionTime+=Math.min(time-lastFrame,100);lastFrame=time;drawPose(activeExercise.id,(1-Math.cos(motionTime/1300))/2);animationFrame=requestAnimationFrame(animate);}
function timerDisplay(){const m=String(Math.floor(remaining/60)).padStart(2,'0'),s=String(remaining%60).padStart(2,'0');$('#timer-value').textContent=m+':'+s;$('#timer-toggle').textContent=timerDeadline?'Pausar':remaining===0?'Repetir descanso':'Iniciar descanso';}
function stopTimer(){clearInterval(timerInterval);timerInterval=0;timerDeadline=null;}
function resetTimer(){stopTimer();remaining=activeExercise?.rest||60;timerDisplay();}
function openExercise(id){if(!plans[activeDay].includes(id)){activeDay=plans.findIndex(p=>p.includes(id));renderRoutine();}activeExercise=getExercise(id);const e=activeExercise;$('#exercise-category').textContent=e.category.toUpperCase();$('#exercise-title').textContent=e.name;$('#exercise-equipment').textContent=e.equipment+' · '+e.muscle;$('#exercise-specs').innerHTML=`<div><strong>${e.sets}</strong><span>SERIES</span></div><div><strong>${e.reps}</strong><span>${e.timed?'SEGUNDOS':'REPETICIONES'}</span></div><div><strong>${e.rest}s</strong><span>DESCANSO</span></div>`;$('#exercise-steps').innerHTML=e.steps.map(s=>'<li>'+s+'</li>').join('');$('#log-reps').parentElement.firstChild.textContent=e.timed?'Segundos por serie':'Reps por serie';const prior=todayRecords().find(r=>r.exercise===id&&r.day===activeDay);$('#log-reps').value=prior?.reps||e.reps;$('#log-load').value=prior?.load||'';$('#exercise-status').textContent=prior?'Ya registrado hoy. Puedes actualizar los valores.':'';$('#complete-exercise').innerHTML=prior?'Actualizar registro <span>✓</span>':'Marcar ejercicio completado <span>✓</span>';resetTimer();motionTime=0;lastFrame=0;$('#toggle-motion').textContent=motionPaused?'Reproducir animación':'Pausar animación';$('#exercise-dialog').showModal();cancelAnimationFrame(animationFrame);drawPose(id,0);animationFrame=requestAnimationFrame(animate);}
document.addEventListener('click',event=>{const exercise=event.target.closest('[data-exercise]');if(exercise){openExercise(exercise.dataset.exercise);return;}const close=event.target.closest('[data-close]');if(close){$('#'+close.dataset.close).close();return;}const check=event.target.closest('[data-check]');if(check){const id=check.dataset.check;if(isDone(id)){records=records.filter(r=>!(r.exercise===id&&r.day===activeDay&&localDay(r.date)===localDay(new Date())));save();renderRoutine();toast('Ejercicio desmarcado.');}else openExercise(id);}});
$$('.nav').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
$$('.brand').forEach(b=>b.addEventListener('click',()=>{showView('rutina');if($('#login-dialog').open)$('#login-dialog').close();}));
$$('.day').forEach(b=>b.addEventListener('click',()=>{activeDay=Number(b.dataset.day);renderRoutine();}));
$$('.day').forEach((b,i)=>b.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();activeDay=event.key==='Home'?0:event.key==='End'?2:(i+(event.key==='ArrowRight'?1:2))%3;renderRoutine();$$('.day')[activeDay].focus();}));
$('#start-session').addEventListener('click',()=>openExercise(plans[activeDay].find(id=>!isDone(id))||plans[activeDay][0]));
$('#search').addEventListener('input',renderLibrary);
$$('.filter').forEach(b=>b.addEventListener('click',()=>{activeFilter=b.dataset.filter;$$('.filter').forEach(f=>{f.classList.toggle('active',f===b);f.setAttribute('aria-pressed',f===b);});renderLibrary();}));
$('#login-open').addEventListener('click',()=>$('#login-dialog').showModal());
$('#about-open').addEventListener('click',()=>$('#about-dialog').showModal());
$('#google-login').addEventListener('click',()=>{$('#google-status').textContent='Google todavía no está conectado. Puedes explorar la demo sin crear una cuenta.';});
$('#toggle-motion').addEventListener('click',()=>{motionPaused=!motionPaused;$('#toggle-motion').textContent=motionPaused?'Reproducir animación':'Pausar animación';});
$('#complete-exercise').addEventListener('click',()=>{if(!$('#log-reps').reportValidity()||!$('#log-load').reportValidity())return;const reps=Number($('#log-reps').value),load=Number($('#log-load').value||0);const record={exercise:activeExercise.id,day:activeDay,reps,load,date:new Date().toISOString()};const index=records.findIndex(r=>r.exercise===record.exercise&&r.day===record.day&&localDay(r.date)===localDay(new Date()));if(index>=0)records[index]=record;else records.push(record);save();renderRoutine();$('#exercise-status').textContent=storageAvailable?'Registro guardado en este navegador.':'Registro disponible solo durante esta visita.';$('#complete-exercise').innerHTML='Actualizar registro <span>✓</span>';toast('¡Un paso más! Ejercicio registrado.');});
$('#timer-toggle').addEventListener('click',()=>{if(timerDeadline){remaining=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));stopTimer();timerDisplay();return;}if(remaining===0)remaining=activeExercise.rest;timerDeadline=Date.now()+remaining*1000;timerDisplay();timerInterval=setInterval(()=>{remaining=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));if(!remaining){stopTimer();$('#exercise-status').textContent='Descanso terminado. Continúa cuando estés listo.';toast('Tu descanso ha terminado.');}timerDisplay();},250);});
$('#timer-reset').addEventListener('click',resetTimer);
$('#exercise-dialog').addEventListener('close',()=>{cancelAnimationFrame(animationFrame);resetTimer();});
$('#reset-progress').addEventListener('click',()=>{if(!records.length){toast('Todavía no hay registros para borrar.');return;}if(confirm('¿Borrar todos los registros locales de esta demo?')){records=[];save();renderHistory();renderRoutine();toast('Registros de demo borrados.');}});
renderRoutine();renderLibrary();
if(!storageAvailable)toast('El almacenamiento local no está disponible en este navegador.');
